require __DIR__ . '/vendor/autoload.php';
$app = require_once __DIR__ . '/bootstrap/app.php';
$app->make('Illuminate\Contracts\Console\Kernel')->bootstrap();

echo "=== Test 1: OpResettlement main query ===\n";
try {
    $start = microtime(true);
    $rows = DB::connection('sqlsrv')->select("
        SELECT TOP 25 p.*, fn.id as fn_id, fn.mlsfNo as fn_mlsfNo
        FROM (
            SELECT id, prop_id, mlsFNo, fileno, temp_fileno, instrument_type,
                   Grantor, Grantee, party_1, party_2, regNo, op_type,
                   op_serial_number, property_description, location,
                   created_by, created_at, plot_no, tp_no, lgsaOrCity,
                   land_use, system_source,
                   ROW_NUMBER() OVER (PARTITION BY prop_id ORDER BY id DESC) as rn
            FROM pra
            WHERE system_source = 'OSSOPCHANGEOFNAME'
              AND prop_id IS NOT NULL AND prop_id != ''

            UNION ALL

            SELECT ic.id, ic.prop_id, ic.mlsFNo, NULL as fileno, ic.temp_fileno,
                   ic.instrument_type,
                   'Kano State Government' as Grantor, ic.party_1_name as Grantee,
                   'Kano State Government' as party_1, ic.party_1_name as party_2,
                   ic.registration_number as regNo, ic.op_type,
                   ic.op_serial_number, ic.property_description, ic.property_location as location,
                   CAST(ic.created_by AS nvarchar(100)) as created_by, ic.created_at,
                   ic.plot_number as plot_no, ic.tp_no, ic.lga as lgsaOrCity,
                   ic.land_use, 'IC_SOURCE' as system_source,
                   ROW_NUMBER() OVER (PARTITION BY ic.prop_id ORDER BY ic.id DESC) as rn
            FROM instrument_capture ic
            LEFT JOIN pra px ON px.prop_id = ic.prop_id
                            AND px.system_source = 'OSSOPCHANGEOFNAME'
            WHERE ic.instrument_type = 'Occupancy Permit (OP)'
              AND ic.prop_id IS NOT NULL AND ic.prop_id != 0
              AND (ic.is_deleted IS NULL OR ic.is_deleted = 0)
              AND px.id IS NULL
        ) as p
        LEFT JOIN fileNumber fn ON fn.mlsfNo = COALESCE(NULLIF(p.mlsFNo, ''), p.fileno)
        LEFT JOIN mls_file_no mfn ON fn.tracking_id = mfn.tracking_id
            AND mfn.full_file_number = COALESCE(NULLIF(p.mlsFNo, ''), p.fileno)
        LEFT JOIN users cb ON cb.id = TRY_CONVERT(int, p.created_by)
        LEFT JOIN (
            SELECT tot_inner.prop_id, MAX(tot_inner.created_at) as latest_tot_created_at
            FROM pra tot_inner
            WHERE tot_inner.instrument_type LIKE '%Transfer of Title%'
               OR tot_inner.transaction_type LIKE '%Transfer of Title%'
            GROUP BY tot_inner.prop_id
        ) tot_agg ON tot_agg.prop_id = p.prop_id
        WHERE p.rn = 1
          AND (fn.is_deleted IS NULL OR fn.is_deleted = 0)
        ORDER BY mfn.con_commissioned_at DESC
    ");
    $elapsed = round((microtime(true) - $start) * 1000);
    echo "  OK - {$elapsed}ms - " . count($rows) . " rows\n";
} catch (\Throwable $e) {
    echo "  ERROR: " . $e->getMessage() . "\n";
}

echo "\n=== Test 2: Card counts ===\n";
try {
    $start = microtime(true);
    $counts = DB::connection('sqlsrv')->selectOne("
        SELECT COUNT(DISTINCT prop_id) as total_commissioned,
            SUM(CASE WHEN land_use LIKE '%RES%' OR land_use LIKE '%res%' THEN 1 ELSE 0 END) as res_count,
            SUM(CASE WHEN land_use LIKE '%COM%' OR land_use LIKE '%com%' THEN 1 ELSE 0 END) as com_count,
            SUM(CASE WHEN land_use LIKE '%IND%' OR land_use LIKE '%ind%' THEN 1 ELSE 0 END) as ind_count,
            SUM(CASE WHEN land_use LIKE '%AGR%' OR land_use LIKE '%agr%' THEN 1 ELSE 0 END) as agr_count
        FROM pra
        WHERE system_source = 'OSSOPCHANGEOFNAME'
          AND prop_id IS NOT NULL AND prop_id != ''
    ");
    $elapsed = round((microtime(true) - $start) * 1000);
    echo "  OK - {$elapsed}ms - total: {$counts->total_commissioned}\n";
} catch (\Throwable $e) {
    echo "  ERROR: " . $e->getMessage() . "\n";
}

echo "\n=== Test 3: ApplicationController PRA subquery (no UPPER) ===\n";
try {
    $start = microtime(true);
    $rows = DB::connection('sqlsrv')->select("
        SELECT TOP 25 oa.id, oa.applicant_name, oa.file_no,
            (SELECT TOP 1 p.plot_no FROM pra p WHERE p.temp_fileno = oa.file_no OR p.mlsFNo = oa.file_no OR p.fileno = oa.file_no ORDER BY p.id DESC) as pra_plot_no,
            (SELECT TOP 1 fi.location FROM file_indexings fi WHERE fi.file_number = oa.file_no ORDER BY fi.id DESC) as fi_location,
            (SELECT TOP 1 fn.location FROM fileNumber fn WHERE fn.mlsfNo = oa.file_no ORDER BY fn.id DESC) as fn_location
        FROM oss_applications oa
        LEFT JOIN instrument_capture ic ON ic.id = oa.instrument_capture_id
        ORDER BY oa.id DESC
    ");
    $elapsed = round((microtime(true) - $start) * 1000);
    echo "  OK - {$elapsed}ms - " . count($rows) . " rows\n";
} catch (\Throwable $e) {
    echo "  ERROR: " . $e->getMessage() . "\n";
