{"content": "<?php
/**
 * Diagnostic: check 3 production issues on op-resettlement page
 */
require __DIR__ . '/vendor/autoload.php';
$app = require_once __DIR__ . '/bootstrap/app.php';
$kernel = $app->make(Illuminate\Contracts\Http\Kernel::class);
$request = Illuminate\Http\Request::create('http://localhost/test');
$app->instance('request', $request);
$kernel->bootstrap();

echo "=== ISSUE 1: Row multiplication from JOINs ===\n";

// Count base PRA records (OSSOPCHANGEOFNAME, unique prop_id)
$praBase = DB::connection('sqlsrv')->selectOne("
    SELECT COUNT(*) as cnt FROM (
        SELECT prop_id, ROW_NUMBER() OVER (PARTITION BY prop_id ORDER BY id DESC) as rn
        FROM pra WHERE system_source = 'OSSOPCHANGEOFNAME' AND prop_id IS NOT NULL AND prop_id != ''
    ) t WHERE rn = 1
");
echo "PRA base (unique prop_id, rn=1): {$praBase->cnt}\n";

// Count IC records without PRA match
$icBase = DB::connection('sqlsrv')->selectOne("
    SELECT COUNT(*) as cnt FROM (
        SELECT ic.prop_id, ROW_NUMBER() OVER (PARTITION BY ic.prop_id ORDER BY ic.id DESC) as rn
        FROM instrument_capture ic
        LEFT JOIN pra px ON px.prop_id = ic.prop_id AND px.system_source = 'OSSOPCHANGEOFNAME'
        WHERE ic.instrument_type = 'Occupancy Permit (OP)' AND ic.prop_id IS NOT NULL AND ic.prop_id != 0
          AND (ic.is_deleted IS NULL OR ic.is_deleted = 0) AND px.id IS NULL
    ) t WHERE rn = 1
");
echo "IC base (unique prop_id, no PRA, rn=1): {$icBase->cnt}\n";
echo "Total base expected: " . ($praBase->cnt + $icBase->cnt) . "\n";

// Check fileNumber duplicates
$fnDupes = DB::connection('sqlsrv')->select("
    SELECT mlsfNo, COUNT(*) as cnt FROM fileNumber
    WHERE mlsfNo IS NOT NULL AND mlsfNo != ''
    GROUP BY mlsfNo HAVING COUNT(*) > 1
    ORDER BY cnt DESC
");
echo "\nfileNumber duplicates (mlsfNo with >1 row): " . count($fnDupes) . "\n";
foreach (array_slice($fnDupes, 0, 5) as $d) echo "  {$d->mlsfNo}: {$d->cnt} rows\n";

// Check mls_file_no duplicates
$mfnDupes = DB::connection('sqlsrv')->select("
    SELECT full_file_number, tracking_id, COUNT(*) as cnt FROM mls_file_no
    WHERE full_file_number IS NOT NULL AND full_file_number != ''
    GROUP BY full_file_number, tracking_id HAVING COUNT(*) > 1 ORDER BY cnt DESC
");
echo "\nmls_file_no duplicates (ffn+tracking_id >1 row): " . count($mfnDupes) . "\n";
foreach (array_slice($mfnDupes, 0, 5) as $d) echo "  {$d->full_file_number} (trk {$d->tracking_id}): {$d->cnt}\n";

echo "\n=== ISSUE 2: Transfer of Title records missing from table ===\n";

// The PRA base query filters with ROW_NUMBER() OVER (PARTITION BY prop_id ORDER BY id DESC)
// A prop_id can have both OP and Transfer of Title. The ROW_NUMBER takes only 1 per prop_id.
// If the Transfer of Title was inserted AFTER the OP, it gets rn=1 and the OP gets rn=2.
// But we filter WHERE rn=1 and IC also only has instrument_type='Occupancy Permit (OP)'
// So Transfer of Title still shows up if it's the latest PRA row for that prop_id.
// BUT the IC UNION only brings 'Occupancy Permit (OP)' - Transfer of Title from IC won't be in UNION

// Check: how many Transfer of Title records exist?
$tot = DB::connection('sqlsrv')->selectOne("
    SELECT COUNT(*) as cnt FROM pra
    WHERE system_source = 'OSSOPCHANGEOFNAME'
      AND (instrument_type LIKE '%Transfer of Title%' OR transaction_type LIKE '%Transfer of Title%')
");
echo "Transfer of Title PRA rows: {$tot->cnt}\n";

// Check: how many of those have rn=1 (i.e., latest record for their prop_id)?
$totRn1 = DB::connection('sqlsrv')->selectOne("
    SELECT COUNT(*) as cnt FROM (
        SELECT id, prop_id, instrument_type, transaction_type,
               ROW_NUMBER() OVER (PARTITION BY prop_id ORDER BY id DESC) as rn
        FROM pra
        WHERE system_source = 'OSSOPCHANGEOFNAME'
          AND prop_id IS NOT NULL AND prop_id != ''
    ) t WHERE rn = 1
      AND (instrument_type LIKE '%Transfer of Title%' OR transaction_type LIKE '%Transfer of Title%')
");
echo "Transfer of Title with rn=1 (latest for prop_id): {$totRn1->cnt}\n";

// Check: how many prop_ids have BOTH OP + Transfer of Title?
$bothTypes = DB::connection('sqlsrv')->selectOne("
    SELECT COUNT(DISTINCT prop_id) as cnt FROM pra
    WHERE system_source = 'OSSOPCHANGEOFNAME'
      AND prop_id IS NOT NULL AND prop_id != ''
      AND prop_id IN (
          SELECT prop_id FROM pra WHERE system_source = 'OSSOPCHANGEOFNAME'
            AND (instrument_type LIKE '%Transfer of Title%' OR transaction_type LIKE '%Transfer of Title%')
      )
      AND prop_id IN (
          SELECT prop_id FROM pra WHERE system_source = 'OSSOPCHANGEOFNAME'
            AND instrument_type NOT LIKE '%Transfer of Title%'
            AND (transaction_type NOT LIKE '%Transfer of Title%' OR transaction_type IS NULL)
      )
");
echo "prop_ids with BOTH OP + Transfer of Title: {$bothTypes->cnt}\n";

echo "\nProblem: ROW_NUMBER(PARTITION BY prop_id ORDER BY id DESC) takes only the LATEST row.\n";
echo "If Transfer of Title was created AFTER OP, it gets rn=1 and OP gets rn>1 (hidden).\n";
echo "If OP was created AFTER Transfer of Title, OP gets rn=1 and Transfer of Title gets rn>1 (hidden).\n";
echo "BOTH types need to show. The PARTITION BY prop_id approach is WRONG for showing both records.\n";

echo "\n=== ISSUE 3: Dashboard card counts ===\n";

// Current code counts from PRA table only, using SUM without DISTINCT
$counts = DB::connection('sqlsrv')->selectOne("
    SELECT
        COUNT(*) as total_rows,
        COUNT(DISTINCT prop_id) as total_unique_propids,
        SUM(CASE WHEN land_use LIKE '%RES%' THEN 1 ELSE 0 END) as res_raw,
        SUM(CASE WHEN land_use LIKE '%COM%' THEN 1 ELSE 0 END) as com_raw,
        SUM(CASE WHEN land_use LIKE '%IND%' THEN 1 ELSE 0 END) as ind_raw,
        SUM(CASE WHEN land_use LIKE '%AGR%' THEN 1 ELSE 0 END) as agr_raw
    FROM pra
    WHERE system_source = 'OSSOPCHANGEOFNAME'
      AND prop_id IS NOT NULL AND prop_id != ''
");
echo "PRA total rows: {$counts->total_rows}\n";
echo "PRA unique prop_ids: {$counts->total_unique_propids}\n";
echo "Card counts (current raw SUM, counts duplicates): RES={$counts->res_raw}, COM={$counts->com_raw}, IND={$counts->ind_raw}, AGR={$counts->agr_raw}\n";

// Check how many rows exist per prop_id
$avgRows = DB::connection('sqlsrv')->select("
    SELECT rows_per_propid, COUNT(*) as how_many_propids FROM (
        SELECT prop_id, COUNT(*) as rows_per_propid
        FROM pra WHERE system_source = 'OSSOPCHANGEOFNAME' AND prop_id IS NOT NULL AND prop_id != ''
        GROUP BY prop_id
    ) t GROUP BY rows_per_propid ORDER BY rows_per_propid
");
echo "\nRows per prop_id distribution:\n";
foreach ($avgRows as $r) echo "  {$r->rows_per_propid} row(s): {$r->how_many_propids} prop_ids\n";

echo "\nProblem: Many prop_ids have 2 rows (OP + Transfer of Title), so SUM double-counts.\n";
echo "Fix: Use COUNT(DISTINCT prop_id) for total, and count unique prop_ids per land_use.\n";
