                    subBtn.style.cursor = 'default';
                    subBtn.onclick = null; // disable re-click
                };

                // ── Merger: close dialog, keep OP modal active ───────────
                document.getElementById('swal-btn-merger').onclick = function () {
                    Swal.close();
                    resolve('merger');
                };

                // ── Proceed: close dialog, continue to commissioning ─────
