data.content:
Use this SQL Server script on production. It backfills existing FEFR Transfer of Title rows so registration particulars are always 0/0/0.

~~~sql
SET NOCOUNT ON;

BEGIN TRY
    BEGIN TRAN;

    DECLARE @schemaName sysname = N'dbo';
    DECLARE @tableName  sysname = N'pra';
    DECLARE @objName    nvarchar(300) = @schemaName + N'.' + @tableName;
    DECLARE @fullTable  nvarchar(400) = QUOTENAME(@schemaName) + N'.' + QUOTENAME(@tableName);

    -- Detect column names (supports snake_case / camelCase variants)
    DECLARE @txCol sysname =
        CASE
            WHEN COL_LENGTH(@objName, 'transaction_type') IS NOT NULL THEN 'transaction_type'
            WHEN COL_LENGTH(@objName, 'transactionType') IS NOT NULL THEN 'transactionType'
            ELSE NULL
        END;

    DECLARE @instrCol sysname =
        CASE
            WHEN COL_LENGTH(@objName, 'instrument_type') IS NOT NULL THEN 'instrument_type'
            WHEN COL_LENGTH(@objName, 'instrumentType') IS NOT NULL THEN 'instrumentType'
            ELSE NULL
        END;

    DECLARE @serialCol sysname =
        CASE
            WHEN COL_LENGTH(@objName, 'serialNo') IS NOT NULL THEN 'serialNo'
            WHEN COL_LENGTH(@objName, 'serial_no') IS NOT NULL THEN 'serial_no'
            ELSE NULL
        END;

    DECLARE @pageCol sysname =
        CASE
            WHEN COL_LENGTH(@objName, 'pageNo') IS NOT NULL THEN 'pageNo'
            WHEN COL_LENGTH(@objName, 'page_no') IS NOT NULL THEN 'page_no'
            ELSE NULL
        END;

    DECLARE @volumeCol sysname =
        CASE
            WHEN COL_LENGTH(@objName, 'volumeNo') IS NOT NULL THEN 'volumeNo'
            WHEN COL_LENGTH(@objName, 'volume_no') IS NOT NULL THEN 'volume_no'
            ELSE NULL
        END;

    DECLARE @systemSourceCol sysname =
        CASE
            WHEN COL_LENGTH(@objName, 'system_source') IS NOT NULL THEN 'system_source'
            WHEN COL_LENGTH(@objName, 'systemSource') IS NOT NULL THEN 'systemSource'
            ELSE NULL
        END;

    IF @txCol IS NULL OR @instrCol IS NULL OR @serialCol IS NULL OR @pageCol IS NULL OR @volumeCol IS NULL
    BEGIN
        RAISERROR('Required PRA columns were not found. Aborting.', 16, 1);
    END

    -- Base predicate: Transfer of Title rows
    DECLARE @where nvarchar(max) = N'(
        LOWER(ISNULL(CAST(p.' + QUOTENAME(@txCol) + N' AS nvarchar(4000)), '''')) LIKE ''%transfer%title%''
        OR LOWER(ISNULL(CAST(p.' + QUOTENAME(@instrCol) + N' AS nvarchar(4000)), '''')) LIKE ''%transfer%title%''
    )';

    -- Scope to FEFR OSS flow only (safe production scope)
    IF @systemSourceCol IS NOT NULL
    BEGIN
        SET @where += N' AND UPPER(ISNULL(CAST(p.' + QUOTENAME(@systemSourceCol) + N' AS nvarchar(200)), '''')) = ''OSSOPCHANGEOFNAME''';
    END

    DECLARE @sql nvarchar(max);
    DECLARE @matched int = 0;
    DECLARE @updated int = 0;

    -- Preview count
    SET @sql = N'SELECT @cnt = COUNT(1) FROM ' + @fullTable + N' p WHERE ' + @where + N';';
    EXEC sp_executesql @sql, N'@cnt int OUTPUT', @cnt = @matched OUTPUT;

    PRINT 'Rows matched for backfill: ' + CAST(@matched AS varchar(20));

    IF @matched = 0
    BEGIN
        PRINT 'No matching rows found. No changes made.';
        ROLLBACK TRAN;
        RETURN;
    END

    -- Backup table (daily)
    DECLARE @backupTableName sysname = N'pra_regpart_backup_' + CONVERT(varchar(8), GETDATE(), 112);
    DECLARE @backupObj nvarchar(300) = @schemaName + N'.' + @backupTableName;
    DECLARE @fullBackup nvarchar(400) = QUOTENAME(@schemaName) + N'.' + QUOTENAME(@backupTableName);

    IF OBJECT_ID(@backupObj, 'U') IS NULL
    BEGIN
        SET @sql = N'SELECT TOP (0) * INTO ' + @fullBackup + N' FROM ' + @fullTable + N';';
        EXEC(@sql);
    END

    -- Backup matched rows before update
    SET @sql = N'INSERT INTO ' + @fullBackup + N' SELECT * FROM ' + @fullTable + N' p WHERE ' + @where + N';';
    EXEC(@sql);

    -- Apply backfill: serial/page/volume => 0/0/0
    SET @sql = N'
        UPDATE p
        SET ' + QUOTENAME(@serialCol) + N' = ''0'',
            ' + QUOTENAME(@pageCol) + N' = ''0'',
            ' + QUOTENAME(@volumeCol) + N' = ''0''
        FROM ' + @fullTable + N' p
        WHERE ' + @where + N';
        SELECT @rows = @@ROWCOUNT;
    ';

    EXEC sp_executesql @sql, N'@rows int OUTPUT', @rows = @updated OUTPUT;

    PRINT 'Rows updated: ' + CAST(@updated AS varchar(20));

    COMMIT TRAN;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRAN;

    THROW;
END CATCH;
~~~

If you want the global version (all Transfer of Title rows, not only FEFR), I can give you a second script with the FEFR scope removed.

