    {
        $prefix = 'TEMP-';

        // Always allocate a NEW sequence id, marked is_used=1 immediately.
        //
        // Previously this method returned the first row where
        //   created_by = current user AND is_used = 0
        // and only flipped is_used=1 after a successful PRA write
        // (PraRecordService::markTempFilenoAsUsed). However, several flows
        // (instrument_capture, OP capture, OSS) consume the temp_fileno
        // WITHOUT writing PRA, so the sequence row stayed unused and the
        // exact same TEMP-XXXXX was handed out to subsequent OP captures.
        // That produced duplicate temp_filenos in instrument_capture, where
        // multiple unrelated OPs ended up sharing one TEMP and one prop_id.
        try {
            $sequenceId = DB::connection('sqlsrv')->table('temp_fileno_sequence')->insertGetId([
                'created_by' => Auth::id(),
                'is_used'    => 1,
                'created_at' => now(),
                'updated_at' => now(),
            ]);

            return $prefix . str_pad((string) $sequenceId, 5, '0', STR_PAD_LEFT);
        } catch (\Exception $e) {
            \Log::error('Failed to generate temp file number from sequence table: ' . $e->getMessage());

            // Fallback to old method if sequence table fails (e.g. missing table)
            return $this->generateTempFileNumberLegacy();
        }
    }", "oldString": "    private function generateTempFileNumber(): string
    {
        $prefix = 'TEMP-';

        // Use the sequence table to generate a unique ID atomically
        try {
            // Check if there's an unused temp file number for this user
            $existing = DB::connection('sqlsrv')->table('temp_fileno_sequence')
                ->where('created_by', Auth::id())
                ->where('is_used', 0)
                ->orderBy('id', 'asc')
                ->first();

            if ($existing) {
                $sequenceId = $existing->id;
            } else {
                // Use the sequence table to generate a new unique ID atomically
                $sequenceId = DB::connection('sqlsrv')->table('temp_fileno_sequence')->insertGetId([
                    'created_by' => Auth::id(),
                    'is_used' => 0,
                    'created_at' => now(),
                    'updated_at' => now()
                ]);
            }

            return $prefix . str_pad((string) $sequenceId, 5, '0', STR_PAD_LEFT);
        } catch (\Exception $e) {
            \Log::error('Failed to generate temp file number from sequence table: ' . $e->getMessage());

            // Fallback to old method if sequence table fails (e.g. missing table)
            // This ensures backward compatibility if migration didn't run
            return $this->generateTempFileNumberLegacy();
