{"content": "/* ============================================================================
   Simple per-row temp_fileno reassignment
   ----------------------------------------------------------------------------
   Use this when you have a SPECIFIC row in instrument_capture (IC) or
   deed_registrations (DR) that is sharing a temp_fileno with another row.

   How it works
   ------------
   * Inserts a new row into temp_fileno_sequence (atomic, gives a unique id)
   * Builds the new TEMP-XXXXX string from that id
   * Updates the chosen IC or DR row to use the fresh temp_fileno
   * Optionally clears prop_id so the app reallocates a clean one next time
   * Mirrors the change into pra/pic where they reference the OLD temp_fileno
     for the SAME file number (so you don't orphan related rows)

   USAGE
   -----
   1. Run STEP 0 (find the duplicate IDs you want to fix).
   2. For EACH duplicate row you want to move OFF the shared TEMP, fill in
      @target_table and @target_id below, then run STEP 1.
   3. Repeat for every offending row.

   Run inside an explicit transaction so you can ROLLBACK if anything looks
   off.  COMMIT only when verification block at the end is clean.
============================================================================ */

USE klas;
SET NOCOUNT ON;
SET XACT_ABORT ON;


/* ============================================================================
   STEP 0 — find duplicates (read-only).  Run first, copy the IDs you want
   to fix, then move on to STEP 1 one at a time.
============================================================================ */
PRINT '--- IC duplicates ---';
SELECT  ic.id, ic.temp_fileno, ic.mlsFNo, ic.prop_id,
        ic.op_serial_number, ic.instrument_type, ic.created_at
FROM    instrument_capture ic
JOIN   (SELECT temp_fileno
        FROM   instrument_capture
        WHERE  temp_fileno LIKE 'TEMP-%'
        GROUP  BY temp_fileno
        HAVING COUNT(*) > 1) d ON d.temp_fileno = ic.temp_fileno
ORDER BY ic.temp_fileno, ic.id;

PRINT '--- DR duplicates ---';
SELECT  dr.id, dr.temp_fileno, dr.fileno, dr.prop_id, dr.created_at
FROM    deed_registrations dr
JOIN   (SELECT temp_fileno
        FROM   deed_registrations
        WHERE  temp_fileno LIKE 'TEMP-%'
        GROUP  BY temp_fileno
        HAVING COUNT(*) > 1) d ON d.temp_fileno = dr.temp_fileno
ORDER BY dr.temp_fileno, dr.id;


/* ============================================================================
   STEP 1 — reassign ONE row.
   ----------------------------------------------------------------------------
   * Set @target_table to 'IC' or 'DR'
   * Set @target_id    to the offending row id from STEP 0
   * Run the whole block.
   * Inspect the verification SELECT.
   * COMMIT if happy, otherwise ROLLBACK.
============================================================================ */

DECLARE @target_table VARCHAR(2)  = 'IC';      -- 'IC' or 'DR'
DECLARE @target_id    BIGINT      = 0;          -- <<< put the row id here

BEGIN TRAN;

DECLARE @old_temp   VARCHAR(50);
DECLARE @file_no    VARCHAR(100);
DECLARE @new_id     INT;
DECLARE @new_temp   VARCHAR(50);

-- Capture the OLD temp_fileno + file number from the chosen row
IF @target_table = 'IC'
BEGIN
    SELECT @old_temp = temp_fileno,
           @file_no  = mlsFNo
    FROM   instrument_capture WITH (UPDLOCK, HOLDLOCK)
    WHERE  id = @target_id;
END
ELSE IF @target_table = 'DR'
BEGIN
    SELECT @old_temp = temp_fileno,
           @file_no  = fileno
    FROM   deed_registrations WITH (UPDLOCK, HOLDLOCK)
    WHERE  id = @target_id;
END
ELSE
BEGIN
    RAISERROR('@target_table must be ''IC'' or ''DR''.', 16, 1);
    ROLLBACK; RETURN;
END;

IF @old_temp IS NULL
BEGIN
    RAISERROR('Row not found or has no temp_fileno.', 16, 1);
    ROLLBACK; RETURN;
END;

-- Allocate a fresh sequence id (atomic)
INSERT INTO temp_fileno_sequence (created_by, is_used, created_at, updated_at)
VALUES (NULL, 1, GETDATE(), GETDATE());

SET @new_id   = SCOPE_IDENTITY();
SET @new_temp = 'TEMP-' + RIGHT('00000' + CAST(@new_id AS VARCHAR(10)), 5);

-- Apply to the targeted row
IF @target_table = 'IC'
BEGIN
    UPDATE instrument_capture
    SET    temp_fileno = @new_temp,
           prop_id     = NULL,             -- let the app reallocate
           updated_at  = GETDATE()
    WHERE  id = @target_id;
END
ELSE
BEGIN
    UPDATE deed_registrations
    SET    temp_fileno = @new_temp,
           prop_id     = NULL,
           updated_at  = GETDATE()
    WHERE  id = @target_id;
END;

-- Mirror into pra / pic for the SAME file number (only if a file_no exists)
IF @file_no IS NOT NULL AND LEN(LTRIM(RTRIM(@file_no))) > 0
BEGIN
    UPDATE pra
    SET    temp_fileno = @new_temp,
           prop_id     = NULL,
           updated_at  = GETDATE()
    WHERE  temp_fileno = @old_temp
      AND  (mlsFNo = @file_no OR fileno = @file_no);

    UPDATE pic
    SET    temp_fileno = @new_temp,
           prop_id     = NULL,
           updated_at  = GETDATE()
    WHERE  temp_fileno = @old_temp
      AND  (mlsFNo = @file_no OR fileno = @file_no);
END;

-- Verify
PRINT '--- Verification ---';
SELECT @target_table   AS target_table,
       @target_id      AS target_id,
       @old_temp       AS old_temp,
