$md[] = "            foreach (\$pairs as \$p) {";
$md[] = "                fputcsv(\$fp, [";
$md[] = "                    \$p['pid'], \$p['op']->id, \$p['tot']->id,";
$md[] = "                    \$p['op']->mlsFNo ?: \$p['op']->fileno,";
$md[] = "                    \$p['tot']->mlsFNo ?: \$p['tot']->fileno,";
$md[] = "                    \$p['diff']->implode(','),";
$md[] = "                    \$p['op']->party_2,  \$p['tot']->party_2,";
$md[] = "                    \$p['op']->plot_no,  \$p['tot']->plot_no,";
$md[] = "                    \$p['op']->land_use, \$p['tot']->land_use,";
